-- ExamGrind verified daily current-affairs desk: 6 November 2026.
-- Coverage window: substantive official releases published on 5 November, plus a recoverable SEBI release from 4 November.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-11-06-critical-mineral-auctions$$, $$2026-11-06$$,
$$Centre launches ninth critical-mineral auction and third exploration-licence tranche$$,
$$The Ministry of Mines launched the ninth e-auction tranche for 20 critical and strategic mineral blocks, alongside the third tranche for Exploration Licence blocks. The package also applies a 2026 auction-rule change intended to reduce failed second rounds for specified minerals.$$,
$$This connects mineral security, the MMDR framework, auction design and the clean-energy supply chain. It is especially useful for questions that distinguish exploration rights from mining rights.$$,
$$A mineral block auction can offer a Composite Licence or Mining Lease, while an Exploration Licence is for exploration before mining begins. The Ministry says ELs were introduced through section 10BA of the MMDR Act for 29 critical and deep-seated minerals in the Seventh Schedule. The two auctions use different bidding logic: the release describes an ascending forward auction for critical-mineral blocks and a descending reverse auction for EL blocks.$$,
$$Ministry of Mines Launches the Ninth Tranche of Critical Mineral Block Auction and the Third Tranche of Exploration Licence Auction; Unveils Landmark Reform$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333123&lang=2&reg=48$$,
$$Ministry of Mines / Press Information Bureau$$, $$2026-11-05$$,
$$["Twenty critical and strategic mineral blocks are in the ninth tranche.","Exploration Licences are linked to section 10BA of the MMDR Act.","The release identifies 29 critical and deep-seated minerals for ELs in the Seventh Schedule.","A forward auction and a reverse auction are not the same bidding method."]$$::jsonb,
$$[{"question":"Which licence in the announcement is meant to attract investment before mining begins?","answer":"The Exploration Licence; the release links it to exploration of specified critical and deep-seated minerals."}]$$::jsonb,
$${"title":"From mineral prospect to auction","steps":["A prospective block needs exploration evidence.","An EL can support private exploration before mining.","Auction rules determine bidder competition and award process.","Successful projects can feed domestic mineral value chains."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-06-trai-satellite-network-recommendations$$, $$2026-11-06$$,
$$TRAI issues satellite-network authorisation and spectrum recommendations$$,
$$TRAI released recommendations on a framework for Satellite Communication Network Provider Authorisation and the assignment of spectrum to such providers. The document was released by TRAI’s Network, Spectrum and Licensing division on 5 November.$$,
$$The update is useful for telecom regulation and space-economy preparation. It tests the separate roles of the regulator and government: a TRAI recommendation is advice in the regulatory process, not itself an operating licence or a spectrum assignment.$$,
$$Satellite communication can extend connectivity where terrestrial networks are difficult to deploy, but it also requires rules on authorisation, network operation and spectrum. The related consultation material frames the issue under the Telecommunications Act, 2023 and distinguishes network-layer arrangements from end-user telecom services. Students should retain that the release is a recommendation; implementation depends on the competent government action that follows.$$,
$$Recommendations on the Framework for Satellite Communication Network Provider Authorisation, and Assignment of Spectrum to Satellite Communication Network Providers$$,
$$https://www.trai.gov.in/recommendations-framework-satellite-communication-network-provider-authorisation-and-assignment$$,
$$Telecom Regulatory Authority of India$$, $$2026-11-05$$,
$$["TRAI released the recommendations on 5 November 2026.","The issuing division is Network, Spectrum and Licensing.","The subject covers both satellite-network-provider authorisation and spectrum assignment.","A recommendation is not the same as a final authorisation or spectrum assignment."]$$::jsonb,
$$[{"question":"Did TRAI’s release itself grant a satellite operator a licence?","answer":"No. It released recommendations on an authorisation and spectrum-assignment framework; a recommendation is not an individual operating authorisation."}]$$::jsonb,
$${"title":"Satellite-telecom regulatory chain","steps":["Satellite networks need a legal authorisation framework.","TRAI studies the issue and releases recommendations.","The competent government considers the framework and spectrum arrangements.","Authorised networks can support communications subject to applicable conditions."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-06-pralay-user-evaluation-test$$, $$2026-11-06$$,
$$DRDO completes Pralay quasi-ballistic missile flight test in user evaluation$$,
$$DRDO conducted a successful flight test of the quasi-ballistic missile Pralay from Dr APJ Abdul Kalam Island off Odisha on 5 November. The Ministry of Defence says all test objectives were met during user evaluation trials and that induction has become imminent.$$,
$$This is a defence-science item that links indigenous R&D, trial stages and defence production. For prelims, do not overstate the result: the release reports a user-evaluation flight test, not a completed operational induction announcement.$$,
$$The test used range instruments of the Integrated Test Range at Chandipur. Research Centre Imarat, Hyderabad and other DRDO laboratories developed the missile, while Bharat Dynamics Limited is identified as a Development-cum-Production Partner. User evaluation trials involve the prospective users and help assess a system before induction decisions.$$,
$$DRDO conducts successful flight-test of quasi-ballistic missile ‘Pralay’$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333276&lang=2&reg=48$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-11-05$$,
$$["The test was conducted from Dr APJ Abdul Kalam Island off Odisha.","Range instrumentation at Chandipur confirmed the test objectives, according to the release.","Research Centre Imarat, Hyderabad is named among the indigenous developers.","Bharat Dynamics Limited is named as a Development-cum-Production Partner."]$$::jsonb,
$$[{"question":"What stage did the release identify for the Pralay test?","answer":"User evaluation trials; it said induction was imminent, not that induction had already been completed."}]$$::jsonb,
$${"title":"From indigenous development to induction","steps":["DRDO laboratories develop a weapon system.","Industry supports production capability.","User evaluation tests assess the system with defence users.","A successful evaluation can support later induction decisions."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-06-advance-tax-devolution$$, $$2026-11-06$$,
$$Centre advances regular Rs 1.09 lakh crore tax-devolution instalment to States$$,
$$The Union Government released Rs 1,09,019 crore of regular tax devolution to States on 5 November, five days before the normal 10 November release date. The Ministry of Finance linked the advance timing to the festive season and States’ capital, development and welfare expenditure.$$,
$$This is a high-value fiscal-federalism update. It helps students distinguish tax devolution—States’ share in the divisible pool—from grants, loans and a new discretionary scheme.$$,
$$Tax devolution is a constitutional fiscal-transfer route shaped by Finance Commission recommendations. The announcement advances a regular monthly instalment; it should not be treated as proof of a new tax or a new centrally sponsored scheme. The release provides a State-wise allocation table, with Uttar Pradesh receiving the largest listed amount of Rs 19,208 crore.$$,
$$Union Government releases regular tax devolution of Rs 1,09,019 crore to State Governments in advance$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333166&lang=2&reg=48$$,
$$Ministry of Finance / Press Information Bureau$$, $$2026-11-05$$,
$$["The instalment total is Rs 1,09,019 crore.","It was released on 5 November rather than the normal 10 November date.","The release describes it as a regular tax-devolution instalment.","Uttar Pradesh received the largest amount listed: Rs 19,208 crore."]$$::jsonb,
$$[{"question":"Is the announced Rs 1,09,019 crore a new Centrally Sponsored Scheme?","answer":"No. The release describes an advanced regular instalment of tax devolution to States."}]$$::jsonb,
$${"title":"Tax devolution in fiscal federalism","steps":["Union taxes form part of the divisible pool.","Finance Commission principles shape States’ shares.","The Union releases an instalment to States.","States use their fiscal space for budgeted expenditure, including capital and welfare priorities."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-06-vb-g-ram-g-fodder-advisory$$, $$2026-11-06$$,
$$Rural-development and animal-husbandry departments issue fodder-convergence advisory$$,
$$The Departments of Rural Development and Animal Husbandry and Dairying issued a joint advisory to States and Union Territories for fodder security, pasture development and livestock-supportive infrastructure through the VB–G RAM G framework. It identifies 22 relevant works from the framework’s 375 permissible works.$$,
$$This joins rural employment, Panchayati Raj planning, animal husbandry and climate-resilient livelihoods. It is a good test of how a statutory employment-and-asset framework can be used through convergence rather than by creating a separate livestock scheme.$$,
$$The release says the VB–G RAM G Act, 2025 came into force on 1 July 2026 and guarantees 125 days of wage employment per rural household. The advisory asks for bottom-up planning through Viksit Gram Panchayat Plans, State action plans and interdepartmental coordination. It names fodder cultivation and storage, pastures, livestock shelters, milk-collection centres and veterinary facilities among eligible intervention types.$$,
$$Department of Rural Development and DAHD Join Hands to Boost Fodder Production, Strengthen Livestock Infrastructure and Support Rural Livelihoods under VB–G RAM G$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2332844&lang=2&reg=48$$,
$$Ministry of Rural Development / Press Information Bureau$$, $$2026-11-05$$,
$$["The advisory identifies 22 relevant works from 375 permissible VB–G RAM G works.","It was issued jointly by DoRD and DAHD to States and UTs.","The release says the Act provides 125 days of wage employment per rural household.","Planning is to be PRI-led and linked to Viksit Gram Panchayat Plans."]$$::jsonb,
$$[{"question":"Does the joint advisory create an entirely separate fodder-employment law?","answer":"No. It uses convergence under the VB–G RAM G framework and its existing permissible works."}]$$::jsonb,
$${"title":"Fodder security through convergence","steps":["Local planning identifies fodder and livestock needs.","Eligible works are selected under the rural-employment framework.","Departments coordinate livestock, agriculture and rural-development inputs.","Durable local assets can support dairy and livestock livelihoods."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-06-ubc-63-double-cluster$$, $$2026-11-06$$,
$$Indian-led study identifies UBC 63 as two star clusters after a close flyby$$,
$$A study involving Indian astronomers found that the open cluster UBC 63 is actually two distinct clusters, UBC 63A and UBC 63B. The work used European Space Agency Gaia data, machine learning and dynamical simulations to study a rare close encounter.$$,
$$This is a useful science-and-technology brief because it ties an Indian research effort to stellar evolution, open clusters, the Gaia mission and the evidence used to infer a system’s history.$$,
$$An open cluster is a comparatively loose group of stars associated with a common stellar environment, although apparent proximity on the sky can be misleading. The two components of UBC 63 have very different estimated ages—about 21 million and 562 million years—supporting the conclusion that they did not form as one cluster. The study estimates their closest encounter occurred about six million years ago; they are now moving apart rather than being gravitationally bound to each other.$$,
$$Team led by Indian astronomers redefine star cluster UBC 63 as a double cluster system spotted after close flyby$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333191&lang=2&reg=48$$,
$$Ministry of Science and Technology / Press Information Bureau$$, $$2026-11-05$$,
$$["UBC 63 is now described as UBC 63A and UBC 63B.","The analysis used ESA’s Gaia mission data.","The estimated ages are about 21 million years and 562 million years.","The two clusters are moving apart and are not gravitationally bound to each other."]$$::jsonb,
$$[{"question":"What evidence strongly argues against a common origin for UBC 63A and UBC 63B?","answer":"Their markedly different estimated ages—about 21 million versus 562 million years."}]$$::jsonb,
$${"title":"How UBC 63 was reclassified","steps":["Gaia measures stellar positions and motions.","Colour-magnitude evidence suggested two stellar populations.","Simulations tested their past trajectories.","Different ages and a close flyby supported classification as two clusters."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-06-pm-vishwakarma-trifed-market-access$$, $$2026-11-06$$,
$$MSME Ministry and TRIFED link PM Vishwakarma artisans to Tribes India markets$$,
$$The Ministry of MSME signed an MoU with TRIFED to improve market access for eligible tribal artisans registered under PM Vishwakarma. The collaboration proposes onboarding, capacity building, product support and access to the Tribes India retail and online network.$$,
$$The item links artisan welfare, tribal development and market institutions. It is relevant because it tests the difference between a beneficiary-support scheme and the public marketing body that may help take products to buyers.$$,
$$PM Vishwakarma was launched on 17 September 2023 to improve the quality and reach of traditional artisans’ products and services. TRIFED operates under the Ministry of Tribal Affairs and uses the Tribes India retail and marketplace network. The MoU does not automatically enrol every artisan: the release limits the collaboration to eligible tribal artisans registered under PM Vishwakarma and subject to applicable onboarding conditions and policies.$$,
$$Ministry of Micro, Small and Medium Enterprises signs MoU with TRIFED to Strengthen Market Access for PM Vishwakarma Artisans$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333311&lang=2&reg=48$$,
$$Ministry of MSME / Press Information Bureau$$, $$2026-11-05$$,
$$["The MoU is between the Ministry of MSME and TRIFED.","TRIFED is under the Ministry of Tribal Affairs.","PM Vishwakarma was launched on 17 September 2023.","The proposed collection is to use Tribes India outlets and its online marketplace, subject to conditions."]$$::jsonb,
$$[{"question":"Which organisation in the MoU is the tribal marketing body?","answer":"TRIFED, which is under the Ministry of Tribal Affairs and operates the Tribes India network."}]$$::jsonb,
$${"title":"Artisan product to market","steps":["An eligible artisan is registered under PM Vishwakarma.","MSME and TRIFED coordinate onboarding and capability support.","Products receive aggregation, quality or catalogue support where applicable.","Tribes India retail and online channels can expand market access."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-06-sebi-igp-working-group$$, $$2026-11-06$$,
$$SEBI forms working group to review Innovators Growth Platform rules$$,
$$SEBI constituted a working group for a comprehensive review of the Innovators Growth Platform framework under the SEBI (Issue of Capital and Disclosure Requirements) Regulations, 2018. The review addresses whether the framework remains suitable for innovation-led and research-intensive enterprises while maintaining investor protection.$$,
$$This is a strong regulator-and-capital-markets item. It helps students place SEBI’s rule-making work alongside the financing needs of deep-tech, biotechnology, semiconductor and other innovation-led firms.$$,
$$The Innovators Growth Platform is a specialised capital-market framework; it should not be confused with a general start-up registration portal. SEBI’s published terms of reference cover listing eligibility, investor requirements, capital raising, continuing obligations, migration to the Main Board and international benchmarking. A working group reviews and recommends—it does not itself amend the regulations.$$,
$$SEBI Constitutes Working Group to Review the Innovators Growth Platform Framework$$,
$$https://www.sebi.gov.in/media-and-notifications/press-releases/nov-2026/sebi-constitutes-working-group-to-review-the-innovators-growth-platform-framework_105610.html$$,
$$Securities and Exchange Board of India$$, $$2026-11-04$$,
$$["The review concerns the Innovators Growth Platform under the SEBI ICDR Regulations, 2018.","The working group is to examine innovation-led and research-intensive enterprises.","Its terms include listing, investor, capital-raising and post-listing questions.","The group will submit recommendations to SEBI for consideration."]$$::jsonb,
$$[{"question":"Did SEBI’s working-group announcement itself amend the IGP regulations?","answer":"No. The group has been asked to review the framework and submit recommendations to SEBI."}]$$::jsonb,
$${"title":"Regulatory review of an innovation-market platform","steps":["Innovation-led firms have distinct capital-raising needs.","SEBI’s IGP framework sets specialised market rules.","A working group examines eligibility, investors and continuing obligations.","SEBI may consider recommendations for later regulatory action."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-06-sebi-mutual-fund-net-settlement$$, $$2026-11-06$$,
$$SEBI issues cash-market net-settlement framework for mutual fund schemes$$,
$$SEBI issued a circular establishing a framework for net settlement of funds for transactions undertaken by mutual fund schemes in the cash market. The circular is a current capital-markets update for understanding settlement design and mutual-fund market operations.$$,
$$This is relevant for economy and financial-regulation questions because it highlights SEBI’s role in market infrastructure and distinguishes settlement arrangements from investment advice or a mutual fund’s return performance.$$,
$$Settlement is the process through which securities and funds obligations are completed after trades. Net settlement offsets eligible obligations so that only the net payable or receivable amount is settled, whereas gross settlement treats obligations separately. The official circular concerns fund settlement for mutual fund schemes in the cash market; students should not infer that it changes the underlying investment objective of a scheme.$$,
$$Framework for net settlement of funds for transactions undertaken by mutual fund schemes in cash market$$,
$$https://www.sebi.gov.in/legal/circulars/nov-2026/framework-for-net-settlement-of-funds-for-transactions-undertaken-by-mutual-fund-schemes-in-cash-market_105616.html$$,
$$Securities and Exchange Board of India$$, $$2026-11-05$$,
$$["SEBI issued the circular on 5 November 2026.","It concerns mutual fund schemes’ transactions in the cash market.","The circular’s subject is net settlement of funds.","Net settlement is an operational settlement mechanism, not a statement about investment returns."]$$::jsonb,
$$[{"question":"What is being addressed by SEBI’s 5 November circular: a mutual fund’s investment objective or settlement of funds after cash-market transactions?","answer":"Settlement of funds after cash-market transactions undertaken by mutual fund schemes."}]$$::jsonb,
$${"title":"Trade to net settlement","steps":["A mutual fund scheme undertakes eligible cash-market transactions.","Settlement obligations are calculated.","Eligible payables and receivables can be offset under the framework.","The resulting net fund obligation is settled through market infrastructure."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = now(),
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-11-06-critical-mineral-auctions$$,
$$2026-11-06-trai-satellite-network-recommendations$$,
$$2026-11-06-pralay-user-evaluation-test$$,
$$2026-11-06-advance-tax-devolution$$,
$$2026-11-06-vb-g-ram-g-fodder-advisory$$,
$$2026-11-06-ubc-63-double-cluster$$,
$$2026-11-06-pm-vishwakarma-trifed-market-access$$,
$$2026-11-06-sebi-igp-working-group$$,
$$2026-11-06-sebi-mutual-fund-net-settlement$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
